/* From Uiverse.io by alexruix - Tags: email, input */
.__UIV_SCOPE__ .input {
  max-width: 190px;
  height: 44px;
  background-color: #05060f0a;
  border-radius: .5rem;
  padding: 0 1rem;
  border: 2px solid transparent;
  font-size: 1rem;
  transition: border-color .3s cubic-bezier(.25,.01,.25,1) 0s, color .3s cubic-bezier(.25,.01,.25,1) 0s,background .2s cubic-bezier(.25,.01,.25,1) 0s;
}

.__UIV_SCOPE__ .label {
  display: block;
  margin-bottom: .3rem;
  font-size: .9rem;
  font-weight: bold;
  color: #05060f99;
  transition: color .3s cubic-bezier(.25,.01,.25,1) 0s;
}

.__UIV_SCOPE__ .input:hover, .__UIV_SCOPE__ .input:focus, .__UIV_SCOPE__ .input-group:hover .input {
  outline: none;
  border-color: #05060f;
}

.__UIV_SCOPE__ .input-group:hover .label, .__UIV_SCOPE__ .input:focus {
  color: #05060fc2;
}
